+import { createEventCard } from './event-card.js';
+
+export function sortChronologically(events, toItem) {
+  return events
+    .map((event) => ({ item: toItem(event), time: new Date(event.startsAt).getTime() }))
+    .sort((a, b) => a.time - b.time)
+    .map(({ item }) => item);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events, createEventCard);
+}

